parameters.jsCode:
// THE ENVELOPE (design V-A). This Code node runs ONCE for all items, so it
// collapses the N rows of 'Read Sends' into ONE single item. Without this, every row
// would trigger its own upload and its own alert.
// Each item carries the whole row as jsonb in 'row' (see the Read Sends
// query): that way dates arrive as text with microseconds, without going through Date.
const rows = $input.all().map(i => i.json.row).filter(f => f && Object.keys(f).length);

const now  = DateTime.now().setZone('America/Costa_Rica');
const date = now.toFormat('yyyy-MM-dd');

const file_name  = `sends_${date}.json`;
const object_key = `sends/${file_name}`;

// The row count goes INSIDE the file, not only in the name: it is what makes the
// restore verifiable without having to remember how many there were (design B-A, and
// rule 6 of the backup protocol).
const content = JSON.stringify({
  generated_at: now.toISO(),
  table: 'bot.sends',
  rows: rows.length,
  columns: rows.length ? Object.keys(rows[0]) : [],
  data: rows,
}, null, 2);

// JSON and not CSV: CSV cannot tell null from an empty string -and a null sent_at
// MEANS something (design V-C)- and it forces escaping commas inside error_message,
// which is the kind of bug this project has already paid for twice.
return [{
  json: {
    file_name,
    object_key,
    rows: rows.length,
    generated_at: now.toISO(),
    mark: `${now.toISO()} | ${rows.length} | ${object_key}`,
  },
  binary: {
    data: {
      data: Buffer.from(content, 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: file_name,
    },
  },
}];

parameters.query:
insert into bot.config (name, value)
values ('last_backup', $1)
on conflict (name) do update set value = excluded.value;
